div.script:
(function () {
  var d = document.getElementById('gd-d'), c = document.getElementById('gd-c'), o = document.getElementById('gd-out');
  if (d && c && o) {
    var show = function (diam) {
      if (!diam || diam < 12 || diam > 25) { o.innerHTML = 'Revisa el número<small>El diámetro debe estar entre 12 y 25 mm.</small>'; return; }
      var s = Math.round(((diam - 11.54) / 0.8128) * 2) / 2;
      if (s < 3) { o.innerHTML = 'Menor a la medida 3<small>Escríbenos y lo vemos contigo.</small>'; return; }
      if (s > 15) { o.innerHTML = 'Mayor a la medida 15<small>Escríbenos y lo vemos contigo.</small>'; return; }
      o.innerHTML = 'Tu medida: ' + s + '<small>Diámetro ' + diam.toFixed(1) + ' mm · circunferencia ' + (Math.PI * diam).toFixed(1) + ' mm</small>';
    };
    d.addEventListener('input', function () { c.value = ''; show(parseFloat(d.value)); });
    c.addEventListener('input', function () { d.value = ''; show(parseFloat(c.value) / Math.PI); });
  }
  var links = document.querySelectorAll('.gd-toc a'); if (!links.length || !('IntersectionObserver' in window)) return;
  var map = {}; links.forEach(function (a) { map[a.getAttribute('href').slice(1)] = a; });
  var io = new IntersectionObserver(function (es) { es.forEach(function (e) { if (e.isIntersecting) { links.forEach(function (a) { a.classList.remove('on'); }); var a = map[e.target.id]; if (a) a.classList.add('on'); } }); }, { rootMargin: '-30% 0px -60% 0px' });
  document.querySelectorAll('.gd-main section[id]').forEach(function (s) { io.observe(s); });
})();
